export function createTtlCache(options) {
    const { ttlMs, maxEntries } = options;
    if (!(ttlMs > 0)) {
        throw new Error(`createTtlCache: ttlMs must be positive, got ${ttlMs}`);
    }
    if (!(maxEntries > 0)) {
        throw new Error(`createTtlCache: maxEntries must be positive, got ${maxEntries}`);
    }
    const entries = new Map();
    return {
        get(key) {
            const hit = entries.get(key);
            if (!hit)
                return undefined;
            if (hit.expiresAt <= Date.now()) {
                entries.delete(key);
                return undefined;
            }
            return hit.value;
        },
        set(key, value) {
            // Delete before insert so Map insertion order tracks the newest write,
            // which is what the eviction loop below reads as "oldest".
            entries.delete(key);
            entries.set(key, { value, expiresAt: Date.now() + ttlMs });
            while (entries.size > maxEntries) {
                const oldest = entries.keys().next();
                if (oldest.done)
                    break;
                entries.delete(oldest.value);
            }
        },
        delete(key) {
            entries.delete(key);
        },
        clear() {
            entries.clear();
        },
        get size() {
            return entries.size;
        },
    };
}
